H.background();
const cx = H.W*0.5, cy = H.H*0.55, R = 160;
// Intersection point X inside circle, controlled by slider P.px (horizontal offset), animated vertically by t
const px = cx + P.px;
const py = cy + 40*Math.sin(t*0.5);
// keep inside circle
let dx = px - cx, dy = py - cy;
let dist = Math.hypot(dx, dy);
let ix = px, iy = py;
if (dist > R - 20){ const k = (R-20)/dist; ix = cx + dx*k; iy = cy + dy*k; dist = R-20; }
// Chord 1: direction angle phi1 (fixed-ish), find both circle intersections through (ix,iy)
function chordEnds(ix, iy, ang){
  const ux = Math.cos(ang), uy = Math.sin(ang);
  // (ix + s*ux - cx)^2 + (iy + s*uy - cy)^2 = R^2
  const fx = ix - cx, fy = iy - cy;
  const b = 2*(fx*ux + fy*uy);
  const c = fx*fx + fy*fy - R*R;
  const disc = Math.max(0, b*b - 4*c);
  const sq = Math.sqrt(disc);
  const s1 = (-b + sq)/2, s2 = (-b - sq)/2;
  return [[ix+s1*ux, iy+s1*uy, s1],[ix+s2*ux, iy+s2*uy, s2]];
}
const ang1 = 0.45;
const ang2 = 0.45 + Math.PI/2 + 0.25*Math.sin(t*0.4);
const ch1 = chordEnds(ix, iy, ang1);
const ch2 = chordEnds(ix, iy, ang2);
H.circle(cx, cy, R, { stroke: H.colors.grid, width: 2 });
// chords
H.line(ch1[0][0], ch1[0][1], ch1[1][0], ch1[1][1], { color: H.colors.accent, width: 2.5 });
H.line(ch2[0][0], ch2[0][1], ch2[1][0], ch2[1][1], { color: H.colors.accent2, width: 2.5 });
// segment lengths
const a = Math.abs(ch1[0][2]), b = Math.abs(ch1[1][2]);
const c = Math.abs(ch2[0][2]), dd = Math.abs(ch2[1][2]);
// endpoints + intersection
for (const e of [ch1[0],ch1[1]]) H.circle(e[0], e[1], 4, { fill: H.colors.accent });
for (const e of [ch2[0],ch2[1]]) H.circle(e[0], e[1], 4, { fill: H.colors.accent2 });
H.circle(ix, iy, 6, { fill: H.colors.yellow });
H.text("Intersecting chords: a*b = c*d", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("At the crossing, the two segment products are always equal.", 24, 52, { color: H.colors.sub, size: 13 });
H.text("a*b = " + (a*b).toFixed(0) + "   (blue chord)", 24, 80, { color: H.colors.accent, size: 14 });
H.text("c*d = " + (c*dd).toFixed(0) + "   (orange chord)", 24, 100, { color: H.colors.accent2, size: 14 });

