v.grid(); v.axes();
const x1 = P.x1, y1 = P.y1, x2 = P.x2, y2 = P.y2;
const run = x2 - x1, rise = y2 - y1;
const eps = 1e-9;
const m = Math.abs(run) < eps ? Infinity : rise / run;
if (Math.abs(run) < eps) {
  v.line(x1, -6, x1, 6, { color: H.colors.accent, width: 3 });
} else {
  v.line(-8, y1 + m * (-8 - x1), 8, y1 + m * (8 - x1), { color: H.colors.accent, width: 3 });
}
v.line(x1, y1, x2, y1, { color: H.colors.good, width: 2.5 });
v.line(x2, y1, x2, y2, { color: H.colors.yellow, width: 2.5 });
const mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
if (Math.abs(run) < eps) {
  v.line(-8, my, 8, my, { color: H.colors.violet, width: 2.5, dash: [6, 4] });
} else if (Math.abs(rise) < eps) {
  v.line(mx, -6, mx, 6, { color: H.colors.violet, width: 2.5, dash: [6, 4] });
} else {
  const mp = -1 / m;
  v.line(-8, my + mp * (-8 - mx), 8, my + mp * (8 - mx), { color: H.colors.violet, width: 2.5, dash: [6, 4] });
}
const u = mx + 3 * Math.sin(t * 0.7);
const pu = Math.abs(run) < eps ? my + 3 * Math.sin(t * 0.7) : y1 + m * (u - x1);
const pxv = Math.abs(run) < eps ? x1 : u;
v.dot(pxv, pu, { r: 5, fill: H.colors.warn });
v.dot(x1, y1, { r: 6, fill: H.colors.accent2 });
v.dot(x2, y2, { r: 6, fill: H.colors.violet });
H.text("Slope m = rise/run; perp = -1/m", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("rise = " + rise.toFixed(1) + ",  run = " + run.toFixed(1), 24, 52, { color: H.colors.sub, size: 13 });
H.text("m = " + (Math.abs(run) < eps ? "undefined (vertical)" : m.toFixed(2)) + "   perp = " + (Math.abs(run) < eps ? "0" : (Math.abs(rise) < eps ? "undefined" : (-1 / m).toFixed(2))), 24, 72, { color: H.colors.violet, size: 13 });

