let a = P.a, b = P.b, c = P.c;
const m = Math.max(a, b, c);
if (m >= a + b + c - m) { const fix = (a + b + c - m) * 0.98; if (a === m) a = fix; else if (b === m) b = fix; else c = fix; }
const s = (a + b + c) / 2;
const prod = s * (s - a) * (s - b) * (s - c);
const area = prod > 0 ? Math.sqrt(prod) : 0;
const Ax = 1, Ay = 1, Bx = 1 + c, By = 1;
const cosA = (b * b + c * c - a * a) / (2 * b * c);
const ang = Math.acos(Math.max(-1, Math.min(1, cosA)));
const Cx = Ax + b * Math.cos(ang), Cy = Ay + b * Math.sin(ang);
v.path([[Ax, Ay], [Bx, By], [Cx, Cy]], { color: H.colors.accent, width: 3, close: true, fill: H.colors.accent });
v.text("a", (Bx + Cx) / 2 + 0.2, (By + Cy) / 2, { color: H.colors.sub, size: 13 });
