H.background();
const Pm = 20;
const w = Math.max(0.001, Math.min(Pm/2 - 0.001, P.w));
const v = H.plot2d({ xMin: 0, xMax: 10, yMin: 0, yMax: 30 });
v.grid(); v.axes();
const area = x => x * (Pm/2 - x);
v.fn(area, { color: H.colors.accent, width: 3 });
const opt = Pm/4;
v.line(opt, 0, opt, area(opt), { color: H.colors.grid, width: 1.5, dash: [4,4] });
v.dot(opt, area(opt), { r: 6, fill: H.colors.good });
const sweep = (Pm/2) * (0.5 + 0.49 * Math.sin(t * 0.7));
const wv = Math.max(0.001, Math.min(Pm/2 - 0.001, sweep));
v.dot(wv, area(wv), { r: 7, fill: H.colors.accent2 });
v.line(wv, 0, wv, area(wv), { color: H.colors.accent2, width: 1, dash:[3,3] });
const h = Pm/2 - w;
const A = w * h;
H.text("Max area for fixed perimeter", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Perimeter " + Pm + " fixed: area = w*(P/2 - w) peaks at the square", 24, 52, { color: H.colors.sub, size: 13 });
H.text("w = " + w.toFixed(2) + ",  h = " + h.toFixed(2) + ",  area = " + A.toFixed(2), 24, 76, { color: H.colors.accent2, size: 13 });
H.text("optimum: square " + opt.toFixed(1) + " x " + opt.toFixed(1) + " -> area " + area(opt).toFixed(1), 24, 96, { color: H.colors.good, size: 13 });

H.background();
const v = H.plot2d({ xMin: -1, xMax: 7, yMin: -2, yMax: 10 });
v.grid(); v.axes();
const k = P.k;
const f = x => k * x * x - 0.3 * x + 1.5;
const fp = x => 2 * k * x - 0.3;
v.fn(f, { color: H.colors.accent, width: 3 });
const a = 0.5, b = 6;
const slope = (f(b) - f(a)) / (b - a);
v.line(a, f(a), b, f(b), { color: H.colors.violet, width: 2.5 });
v.dot(a, f(a), { r: 5, fill: H.colors.sub });
v.dot(b, f(b), { r: 5, fill: H.colors.sub });
const c = (a + b) / 2;
const sweep = a + 0.2 + (b - a - 0.4) * (0.5 + 0.5 * Math.sin(t * 0.7));
const ts = f(sweep) - fp(sweep) * sweep;
v.line(a, fp(sweep) * a + ts, b, fp(sweep) * b + ts, { color: H.colors.accent2, width: 1.6, dash:[4,4] });
v.dot(sweep, f(sweep), { r: 5, fill: H.colors.accent2 });
v.line(c, -2, c, f(c), { color: H.colors.grid, width:1, dash:[3,3] });
v.dot(c, f(c), { r: 7, fill: H.colors.good });
v.text("c", c, f(c) + 0.9, { color: H.colors.good, size: 13, align:"center" });
H.text("Mean Value Theorem", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Secant slope (a..b) = tangent slope at some c in (a,b)", 24, 52, { color: H.colors.sub, size: 13 });
H.text("secant slope = " + slope.toFixed(2) + " ; c = " + c.toFixed(2) + " where f'(c) = " + fp(c).toFixed(2), 24, 76, { color: H.colors.good, size: 13 });
H.text("probe f'(x) = " + fp(sweep).toFixed(2) + " at x = " + sweep.toFixed(2), 24, 96, { color: H.colors.accent2, size: 13 });

H.background();
const v = H.plot2d({ xMin: -1, xMax: 7, yMin: -2, yMax: 8 });
v.grid(); v.axes();
const a = 1, b = 5;
const k = P.k;
const L = 3;
const f = x => k * (x - a) * (x - b) + L;
const fp = x => k * (2 * x - a - b);
v.fn(f, { color: H.colors.accent, width: 3 });
v.line(a, f(a), b, f(b), { color: H.colors.violet, width: 2, dash:[5,5] });
v.dot(a, f(a), { r: 5, fill: H.colors.sub });
v.dot(b, f(b), { r: 5, fill: H.colors.sub });
v.text("f(a)=f(b)=" + L.toFixed(1), a, L + 0.8, { color: H.colors.violet, size: 12 });
const c = (a + b) / 2;
const sweep = a + 0.2 + (b - a - 0.4) * (0.5 + 0.5 * Math.sin(t * 0.7));
const ts = f(sweep) - fp(sweep) * sweep;
v.line(a, fp(sweep) * a + ts, b, fp(sweep) * b + ts, { color: H.colors.accent2, width: 1.6, dash:[4,4] });
v.dot(sweep, f(sweep), { r: 5, fill: H.colors.accent2 });
v.line(c, -2, c, f(c), { color: H.colors.grid, width:1, dash:[3,3] });
v.line(a, f(c), b, f(c), { color: H.colors.good, width: 2 });
v.dot(c, f(c), { r: 7, fill: H.colors.good });
v.text("c, slope 0", c, f(c) + (k>=0? -0.9: 0.9), { color: H.colors.good, size: 13, align:"center" });
H.text("Rolle's Theorem", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("If f(a)=f(b), some c in (a,b) has f'(c)=0 (horizontal tangent)", 24, 52, { color: H.colors.sub, size: 13 });
H.text("c = " + c.toFixed(2) + " ; f'(c) = " + fp(c).toFixed(2), 24, 76, { color: H.colors.good, size: 13 });
H.text("probe f'(x) = " + fp(sweep).toFixed(2) + " at x = " + sweep.toFixed(2), 24, 96, { color: H.colors.accent2, size: 13 });

H.background();
const a = (P.a === 0 ? 0.001 : P.a);
const yLo = Math.min(-1, a - 1.5);
const yHi = Math.max(2, a + 1.5);
const v = H.plot2d({ xMin: -3, xMax: 3, yMin: yLo, yMax: yHi });
v.grid(); v.axes();
const r = x => (Math.abs(x) < 1e-4 ? a * Math.cos(a * x) : Math.sin(a * x) / x);
v.fn(r, { color: H.colors.accent, width: 3 });
v.line(-3, a, 3, a, { color: H.colors.good, width: 1.5, dash:[5,5] });
v.text("limit = a = " + a.toFixed(2), 0.2, a + (a>=0?0.25:-0.25), { color: H.colors.good, size: 12 });
const x = 2.2 * Math.cos(t * 0.9);
const xs = (Math.abs(x) < 1e-4 ? 1e-4 : x);
const num = Math.sin(a * xs);
const den = xs;
v.dot(xs, num/den, { r: 7, fill: H.colors.accent2 });
v.line(xs, 0, xs, num/den, { color: H.colors.accent2, width:1, dash:[3,3] });
v.circle(0, a, 5, { fill: H.colors.bg, stroke: H.colors.warn, width: 2 });
H.text("L'Hopital's Rule for 0/0", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("sin(a*x)/x is 0/0 at x=0; limit = a*cos(0)/1 = a", 24, 52, { color: H.colors.sub, size: 13 });
H.text("at x=" + xs.toFixed(3) + ":  sin(a*x)=" + num.toFixed(3) + " , x=" + den.toFixed(3) + " , ratio=" + (num/den).toFixed(3), 24, 76, { color: H.colors.accent2, size: 13 });
H.text("derivatives: a*cos(a*x) / 1 -> a as x->0", 24, 96, { color: H.colors.good, size: 13 });

H.background();
const a = P.a;
const f = x => x*x*x - a*x;
const fp = x => 3*x*x - a;
const fpp = x => 6*x;
const sweep = 3.2 * Math.sin(t * 0.5);
const v = H.plot2d({ xMin: -3.4, xMax: 3.4, yMin: -9, yMax: 9, box: { x: 60, y: 40, w: H.W - 320, h: H.H - 80 } });
v.grid(); v.axes();
v.fn(f,   { color: H.colors.accent,  width: 3 });
v.fn(fp,  { color: H.colors.accent2, width: 2 });
v.fn(fpp, { color: H.colors.violet,  width: 2 });
const y0 = f(sweep), s0 = fp(sweep), c0 = fpp(sweep);
v.dot(sweep, y0, { r: 7, fill: H.colors.accent });
const dx = 1.1;
v.line(sweep - dx, y0 - s0*dx, sweep + dx, y0 + s0*dx, { color: H.colors.yellow, width: 2 });
v.dot(sweep, fp(sweep),  { r: 5, fill: H.colors.accent2 });
v.dot(sweep, fpp(sweep), { r: 5, fill: H.colors.violet });
H.legend([
  { label: "f  (curve)", color: H.colors.accent },
  { label: "f '  (slope)", color: H.colors.accent2 },
  { label: "f ''  (concavity)", color: H.colors.violet }
], H.W - 250, 60);
H.text("Curve sketching: f, f ', f ''", 24, 28, { color: H.colors.ink, size: 18, weight: 700 });
H.text("f(x) = x^3 - a*x", 24, 50, { color: H.colors.sub, size: 13 });
const px = H.W - 250;
H.text("at x = " + sweep.toFixed(2), px, 130, { color: H.colors.sub, size: 13 });
H.text("f '  = " + s0.toFixed(2) + (s0 > 0 ? "  rising" : s0 < 0 ? "  falling" : "  flat"), px, 152, { color: H.colors.accent2, size: 13 });
H.text("f '' = " + c0.toFixed(2) + (c0 > 0 ? "  concave up" : c0 < 0 ? "  concave down" : "  inflection"), px, 174, { color: H.colors.violet, size: 13 });

H.background();
const a = P.a;
const f  = x => x*x*x - a*x - 2;
const fp = x => 3*x*x - a;
const v = H.plot2d({ xMin: -3, xMax: 4, yMin: -8, yMax: 12 });
v.grid(); v.axes();
v.fn(f, { color: H.colors.accent, width: 3 });
const x0 = -2.4;
const xs = [x0];
for (let i = 0; i < 6; i++) {
  const xc = xs[xs.length - 1];
  const d = fp(xc);
  const nx = Math.abs(d) < 1e-6 ? xc : xc - f(xc) / d;
  xs.push(Math.max(-3, Math.min(4, nx)));
}
const steps = Math.min(xs.length - 1, 1 + Math.floor((t % 8) / 1.4));
for (let i = 0; i < steps; i++) {
  const xc = xs[i], yc = f(xc), nx = xs[i + 1];
  v.dot(xc, yc, { r: 4, fill: H.colors.accent });
  v.line(xc, yc, nx, 0, { color: H.colors.yellow, width: 2 });
  v.line(xc, 0, xc, yc, { color: H.colors.grid, width: 1, dash: [4, 4] });
}
const cur = xs[steps];
v.dot(cur, 0, { r: 7, fill: H.colors.good });
v.circle(cur, 0, 11, { stroke: H.colors.good, width: 2 });
H.text("Newton's method: x_{n+1} = x_n - f(x_n)/f '(x_n)", 24, 28, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Follow each tangent down to the x-axis to refine the root", 24, 50, { color: H.colors.sub, size: 13 });
H.text("step " + steps + "    x = " + cur.toFixed(5), 24, 74, { color: H.colors.good, size: 13 });
H.text("f(x) = " + f(cur).toFixed(5), 24, 94, { color: H.colors.sub, size: 13 });

H.background();
const A = P.A, w = P.w;
const pos = tt => A * Math.sin(w * tt);
const vel = tt => A * w * Math.cos(w * tt);
const acc = tt => -A * w * w * Math.sin(w * tt);
const tMax = 6.2832 / Math.max(w, 0.2);
const now = (t * 0.6) % tMax;
const colW = H.W - 200;
const ph = (H.H - 70) / 3;
const ymax = A * Math.max(1, w, w * w) * 1.15 + 0.1;
const panel = (yTop, fn, col, label) => {
  const view = H.plot2d({ xMin: 0, xMax: tMax, yMin: -ymax, yMax: ymax,
    box: { x: 60, y: yTop, w: colW, h: ph - 18 } });
  view.grid(); view.axes();
  view.fn(fn, { color: col, width: 3 });
  view.dot(now, fn(now), { r: 6, fill: col });
  view.line(now, -ymax, now, ymax, { color: H.colors.grid, width: 1, dash: [3, 3] });
  H.text(label + " = " + fn(now).toFixed(2), 70, yTop + 4, { color: col, size: 13, weight: 700 });
};
panel(54,            pos, H.colors.accent,  "x(t)");
panel(54 + ph,       vel, H.colors.accent2, "v(t)");
panel(54 + 2 * ph,   acc, H.colors.violet,  "a(t)");
const px = H.W - 130, mid = H.H / 2;
H.line(px, 70, px, H.H - 16, { color: H.colors.grid, width: 1 });
const scale = ph * 0.7 / ymax;
const py = mid - pos(now) * scale;
H.circle(px, py, 9, { fill: H.colors.accent });
H.arrow(px, py, px, py - vel(now) * scale, { color: H.colors.accent2, width: 3 });
H.text("particle", px - 20, 54, { color: H.colors.sub, size: 12 });
H.text("Position -> Velocity -> Acceleration", 24, 28, { color: H.colors.ink, size: 18, weight: 700 });
H.text("t = " + now.toFixed(2) + "s   v is slope of x,  a is slope of v", 320, 28, { color: H.colors.sub, size: 13 });
